@RunWith(JUnit4.class)
public class WriteableCommandLineImpl_getValues_TriageGen2Test {















    @Test
    public void testGetValues_NullOption() throws OptionException {
        // given
        Option option = null;
        List defaultValues = new ArrayList();
        defaultValues.add("default-value");
        WriteableCommandLineImpl writeableCommandLine = new WriteableCommandLineImpl(option, defaultValues);

        // when
        List result = writeableCommandLine.getValues(option, defaultValues);

        // then
        assertNotNull(result);
        assertTrue(result.isEmpty());
    }


}
